/// <summary>
/// CB626_TMSEngineSOPackingSlip
/// Class responsible for the creation of a METTMSShipmentItemGroup record
/// </summary>
abstract class METTMSShipmentItemGroupUOM
{
    METTMSEngineSalesOrderProccessLinesTmp processLinesTmp;
    METTMSEngineSalesOrderProccessLinesTmp lineTmpSum;
    METTMSShipmentOrderIdentifier          tmsShipmentOrderIdentifier;
    boolean                                isKegItem, isToteCustomer;
    InventParameters                       inventParameters;
    InventLocationId                       headerInventLocationId;

    METWHSPalletVolume  sumRepackContainersByCommodityCaseVolume, sumRepackContainersByCommodityToteVolume;
    int                 sumRepackContainersByCommodityQty;
    METWHSPalletWeight  sumRepackContainersByCommodityToteWeight;

    // CCR
    METWHSPalletVolume  sumRepackContainersByCommodityCaseVolumeCCR, sumRepackContainersByCommodityToteVolumeCCR;
    int                 sumRepackContainersByCommodityQtyCCR;
    METWHSPalletWeight  sumRepackContainersByCommodityToteWeightCCR;

    // Pallet volume & weight use SO's main warehouse
    METWHSPalletVolume  whsPalletVolume;
    METWHSPalletWeight  whsPalletWeight;

    Set ccrToteIds;

    SalesId             salesId;
    WMSPickingRouteId   pickingRouteId;

}

